package io.airtap.preview;
import org.json.*;import java.util.*;import android.os.SystemClock;
public final class MigrationRecoveryTest {
 static final String A="a".repeat(32),B="b".repeat(32);static int passed;static TrustedGrant trust;static EnrollmentStore.Config config;static String id,fence;static MigrationRecovery.Outcome outcome;
 interface Check{void run()throws Exception;}static void check(boolean v){if(!v)throw new AssertionError();}
 static void reboot()throws Exception{java.lang.reflect.Field f=MigrationRecovery.class.getDeclaredField("attempt");f.setAccessible(true);f.set(null,null);FakeDisk.reboot();trust=new TrustedGrant(new android.content.Context());outcome=null;RelayApi.requests.clear();}
 static void reset()throws Exception{FakeDisk.reset();reboot();config=new EnrollmentStore.Config("https://synthetic.invalid/d/"+A,"e".repeat(64));FakeDisk.config=config;String c=trust.beginApproval(config,A,"Synthetic A");trust.completeApproval(config,c);trust.consume(config,7);fence=trust.sessionFence(config);id=trust.beginMigration(config,fence);SystemClock.now=100000;}
 static void test(String name,Check fn)throws Exception{reset();fn.run();passed++;System.out.println("PASS "+name);}
 static JSONObject single(String claim){return RelayApi.json("protocol_version",4,"state","approved","candidate",RelayApi.json("claim_id",claim),"session_expires_at",JSONObject.NULL,"allow_tap",false,"persistent",true,"all_apps",true,"allow_control",true,"allowed_packages",new JSONArray());}
 static JSONObject multi(String claim){JSONArray grants=new JSONArray();if(claim!=null)grants.put(RelayApi.json("claim_id",claim,"name","Synthetic A","state","approved","command_sequence",8,"lease_required",false,"lease_ready",false,"persistent",true,"all_apps",true,"allow_control",true,"allowed_packages",new JSONArray()));return RelayApi.json("protocol_version",4,"mode","multi","generation",0,"max_grants",4,"invitation_sequence",0,"grants",grants,"invitation",JSONObject.NULL);}
 static void resume()throws Exception{check(MigrationRecovery.resume(new android.content.Context(),config,r->outcome=r));}
 static RelayApi.Request last(){return RelayApi.requests.get(RelayApi.requests.size()-1);}
 static void post()throws Exception{resume();check(last().method.equals("GET"));last().respond(single(A),200,null);check(last().method.equals("POST"));}
 static void unchanged()throws Exception{check(!trust.multi(config)&&trust.isCurrent(config,fence)&&trust.read(config).getLong("sequence")==7);}
 public static void main(String[]args)throws Exception{
  test("unknown authentication statuses preserve migration and original consent",()->{for(int status:new int[]{401,403,410}){reset();resume();last().respond(null,status,"unknown edge response");unchanged();check(outcome==MigrationRecovery.Outcome.RETRY&&trust.migration(config)!=null);}});
  test("unknown first enable rejection cannot abandon migration",()->{for(int status:new int[]{404,409}){reset();post();last().respond(null,status,"unknown response");unchanged();check(outcome==MigrationRecovery.Outcome.RETRY&&trust.migration(config)!=null&&RelayApi.requests.size()==2);}});
  test("verified device retirement stops original migration and fences later success",()->{resume();var old=last();old.respond(RelayApi.json("protocol_version",4,"error","device_unenrolled"),410,"retired");check(outcome==MigrationRecovery.Outcome.STOPPED&&trust.read(config)==null);old.respond(multi(A),200,null);check(trust.read(config)==null&&outcome==MigrationRecovery.Outcome.SUPERSEDED);});
  test("malformed successful pairing response never erases migration",()->{resume();last().respond(single(A).put("all_apps","true"),200,null);unchanged();check(outcome==MigrationRecovery.Outcome.RETRY&&trust.migration(config)!=null);});
  test("confirmation persists only prepared intent and POST persists unknown before sending",()->{unchanged();check(trust.migration(config).getString("phase").equals("prepared"));post();unchanged();check(trust.migration(config).getString("phase").equals("unknown")&&last().body.getJSONArray("capabilities").length()==2&&last().body.getString("expected_claim_id").equals(A));});
  test("verified remote commit preserves latest single sequence and claim",()->{post();trust.consume(config,8);last().respond(multi(A),200,null);check(outcome==MigrationRecovery.Outcome.COMMITTED&&trust.multi(config)&&trust.grant(config,A).getLong("sequence")==8&&trust.migration(config)==null);});
  test("first explicit 404 or 409 plus same single read abandons only migration",()->{for(int status:new int[]{404,409}){reset();post();last().respond(RelayApi.json("protocol_version",4,"error",status==404?"not_found":"unsupported_state_schema"),status,"rejected");check(last().method.equals("GET"));last().respond(single(A),200,null);unchanged();check(outcome==MigrationRecovery.Outcome.REJECTED&&trust.migration(config)==null);}});
  test("lost enable response is reconciled after process restart without another POST",()->{post();last().respond(null,0,"network");check(outcome==MigrationRecovery.Outcome.RETRY);reboot();resume();last().respond(multi(A),200,null);check(outcome==MigrationRecovery.Outcome.COMMITTED&&trust.multi(config)&&RelayApi.requests.size()==1);});
  test("historical unknown cannot be canceled by a later single read and 404",()->{post();last().respond(null,503,"unknown");reboot();post();last().respond(RelayApi.json("protocol_version",4,"error","not_found"),404,"old_service");unchanged();check(outcome==MigrationRecovery.Outcome.RETRY&&trust.migration(config).getString("phase").equals("unknown")&&RelayApi.requests.size()==2);});
  test("crash after dispatch before callback stays unknown and cannot downgrade",()->{post();reboot();post();last().respond(RelayApi.json("protocol_version",4,"error","unsupported_state_schema"),409,"rejected");unchanged();check(outcome==MigrationRecovery.Outcome.RETRY&&trust.migration(config)!=null);});
  test("failed durable dispatch write sends no POST",()->{resume();FakeDisk.failSaveAt=FakeDisk.saves+1;last().respond(single(A),200,null);unchanged();check(outcome==MigrationRecovery.Outcome.RETRY&&RelayApi.requests.size()==1&&trust.migration(config).getString("phase").equals("prepared"));});
  test("failed local schema commit remains unknown and can reconcile remote success",()->{post();FakeDisk.failSaveAt=FakeDisk.saves+1;last().respond(multi(A),200,null);unchanged();check(outcome==MigrationRecovery.Outcome.RETRY&&trust.migration(config)!=null);reboot();resume();last().respond(multi(A),200,null);check(outcome==MigrationRecovery.Outcome.COMMITTED&&trust.multi(config));});
  test("secondary marker failure after schema save is committed and STOP still fences",()->{post();FakeDisk.preferences.failAt=FakeDisk.preferences.calls+1;last().respond(multi(A),200,null);check(outcome==MigrationRecovery.Outcome.COMMITTED&&trust.multi(config));trust.stop();reboot();check(trust.read(config)==null&&trust.grants(config).isEmpty());});
  test("STOP fences delayed successful remote response",()->{post();var old=last();trust.stop();old.respond(multi(A),200,null);check(outcome==MigrationRecovery.Outcome.SUPERSEDED&&trust.read(config)==null&&!trust.multi(config));});
  test("same claim reapproval cannot be replaced by old migration callback",()->{post();var old=last();trust.stop();String consent=trust.beginApproval(config,A,"New consent");trust.completeApproval(config,consent);trust.consume(config,11);old.respond(multi(A),200,null);check(outcome==MigrationRecovery.Outcome.SUPERSEDED&&!trust.multi(config)&&trust.read(config).getLong("sequence")==11);});
  test("changed enrollment blocks delayed remote commit",()->{post();FakeDisk.config=new EnrollmentStore.Config(config.url,"f".repeat(64));last().respond(multi(A),200,null);unchanged();check(outcome==MigrationRecovery.Outcome.SUPERSEDED);});
  test("remote multi missing original claim commits empty mode and never creates another grant",()->{post();last().respond(multi(B),200,null);check(outcome==MigrationRecovery.Outcome.COMMITTED&&trust.read(config)==null&&trust.grant(config,B)==null&&trust.multi(config));});
  test("read-only reconciliation recognizes removed or replaced original single grant",()->{for(JSONObject response:List.of(single(B),RelayApi.json("protocol_version",4,"state","revoked"))){reset();resume();last().respond(response,200,null);check(outcome==MigrationRecovery.Outcome.STOPPED&&trust.read(config)==null&&RelayApi.requests.size()==1);}});
  test("malformed multi does not invent success or remove original consent",()->{post();last().respond(multi(A).put("invitation",null),200,null);unchanged();check(outcome==MigrationRecovery.Outcome.RETRY&&trust.migration(config)!=null);});
  test("failed reconciliation after first rejection retains unknown",()->{post();last().respond(RelayApi.json("protocol_version",4,"error","not_found"),404,"rejected");last().respond(null,0,"offline");unchanged();check(outcome==MigrationRecovery.Outcome.RETRY&&trust.migration(config)!=null);});
  test("unreadable current trust preserves stored intent and grant",()->{post();FakeDisk.failReadRecord=true;last().respond(multi(A),200,null);FakeDisk.failReadRecord=false;unchanged();check(outcome==MigrationRecovery.Outcome.RETRY&&trust.migration(config)!=null);});
  test("inflight and retry backoff suppress duplicate requests",()->{resume();check(!MigrationRecovery.resume(new android.content.Context(),config,null));last().respond(null,503,"offline");check(!MigrationRecovery.resume(new android.content.Context(),config,null));SystemClock.now+=5000;resume();check(RelayApi.requests.size()==2);});
  test("durable original claim revoke blocks migration even when encrypted stop fails",()->{post();OwnerRevocations.queue(new android.content.Context(),config,A);int saves=FakeDisk.saves;last().respond(multi(A),200,null);check(outcome==MigrationRecovery.Outcome.SUPERSEDED&&!trust.multi(config)&&FakeDisk.saves==saves&&trust.read(config)!=null);});
  System.out.println("TOTAL "+passed);
 }
}
